component-sizing.value:
color-mix(
    in srgb,
    var(--fui-text-primary) calc(var(--_fui-chrome) * 100%),
    var(--fui-color-accent)
  )

color-mix(
    in srgb,
    color-mix(in srgb, var(--fui-text-primary) 90%, var(--fui-bg-primary))
      calc(var(--_fui-chrome) * 100%),
    var(--fui-color-accent-hover)
  )

color-mix(
    in srgb,
    color-mix(in srgb, var(--fui-text-primary) 82%, var(--fui-bg-primary))
      calc(var(--_fui-chrome) * 100%),
    var(--fui-color-accent-active)
  )

color-mix(
    in srgb,
    var(--fui-bg-primary) calc(var(--_fui-chrome) * 100%),
    var(--fui-color-on-accent)
  )
